<?php namespace App\Http\Controllers\Api\Web; use App\Helpers\CountryHelper; use App\Http\Controllers\Controller; use App\Models\Employee; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; class EmployerEmployeeController extends Controller { /** * Get a list of employees for use in attachment modals. * V2.4-S15 (Plan B): Admin/Staff can retrieve all employees (bypassing tenancy scope). * Employer users are automatically limited by employerTenancy Global Scope. */ public function index(Request $request): JsonResponse { $user = Auth::user(); if (!$user->hasRole('employer') && !$user->can('manage-tickets')) { return response()->json(['error' => 'Unauthorized'], 403); } // --- START PLAN B (V2.4-S15) IMPLEMENTATION --- if ($user->can('manage-tickets')) { // Staff/Admin can view all employees by explicitly bypassing the global scope // We must eager load 'employer' to get the name for the modal display $query = Employee::withoutGlobalScopes(['employerTenancy'])->with('employer'); [cite: 2-5] } else { // Employer is fetching (Global Scope 'employerTenancy' will apply automatically) // We also eager load 'employer' here, though it might be redundant, it standardizes the data $query = Employee::with('employer'); [cite: 2-5] } // Fetch necessary fields, ensuring employer_id is included for frontend filtering. $employees = $query ->whereNull('terminated_at') ->orderBy('employeeNameTh') // Fetch all fields needed for modal display and filtering ->get(['id', 'employeeNameTh', 'employeeNameEn', 'employeePassport', 'companyWorkerId', 'employeePhoto', 'employeeNationality', 'employer_id']); // Ensure photo accessor runs $employees->append('photo_url'); // --- END PLAN B (V2.4-S15) IMPLEMENTATION --- $employeesData = $employees->map(function ($employee) { $nationality = $employee->employeeNationality; // V2.4-S11.4: Use helper correctly (based on original file) [cite: 14-16] $countryCode = CountryHelper::getCountryCode($nationality); $flagUrl = $countryCode ? asset('images/flags/' . strtolower($countryCode) . '.png') : null; // Add employer information (required for Admin/Staff filter and display) // Check if employer relationship is loaded before accessing properties $employerName = $employee->employer ? $employee->employer->employerNameTh : 'N/A'; $employerId = $employee->employer_id; return [ 'id' => $employee->id, 'employeeNameTh' => $employee->employeeNameTh, 'employeeNameEn' => $employee->employeeNameEn, 'employeePassport' => $employee->employeePassport, 'companyWorkerId' => $employee->companyWorkerId, 'photo_url' => $employee->photo_url, // Accessor field [cite: 14-16] 'nationality' => $nationality, 'flag_url' => $flagUrl, 'employer_id' => $employerId, // Critical for filtering 'employer_name' => $employerName, // Critical for display ]; }); return response()->json($employeesData); } }